const update = $json;
const callback = update.callback_query ?? null;
const message = update.message ?? callback?.message ?? {};
const from = update.message?.from ?? callback?.from ?? {};
const chat = message.chat ?? {};
const rawMessageText = typeof update.message?.text === 'string' ? update.message.text : '';
const trimmedRawMessageText = rawMessageText.trim();
const callbackData = typeof callback?.data === 'string' ? callback.data : '';
const accessPassword = process.env.BOT_ACCESS_PASSWORD ?? '';
const accessPasswordConfigured = accessPassword.length > 0;
const accessPasswordMatched = accessPasswordConfigured && trimmedRawMessageText === accessPassword;
const messageText = accessPasswordMatched ? '[access-password]' : '';
const trimmedText = '';
const command = '';

const numberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

return [
  {
    json: {
      updateType: callback ? 'callback_query' : 'message',
      telegramUserId: numberOrNull(from.id),
      chatId: numberOrNull(chat.id),
      messageId: numberOrNull(message.message_id),
      callbackQueryId: callback?.id ?? '',
      callbackData,
      messageText,
      trimmedText,
      command,
      isTextMessage: Boolean(update.message && typeof update.message.text === 'string'),
      isCallback: Boolean(callback),
      username: from.username ?? '',
      firstName: from.first_name ?? '',
      lastName: from.last_name ?? '',
      accessPasswordConfigured,
      accessPasswordMatched,
      settings: {
        maxAgentsPerUser: Number.parseInt(process.env.MAX_AGENTS_PER_USER ?? '3', 10),
        defaultPrompt: process.env.DEFAULT_AGENT_PROMPT ?? 'You are a helpful voice assistant.',
        defaultWelcome: process.env.DEFAULT_AGENT_WELCOME ?? 'Hello, how can I help you today?',
        defaultLanguage: process.env.DEFAULT_AGENT_LANGUAGE ?? 'en',
        defaultVoiceId: process.env.DEFAULT_AGENT_VOICE_ID ?? 'cjVigY5qzO86Huf0OWal',
        defaultTtsModelId: process.env.DEFAULT_AGENT_TTS_MODEL_ID ?? 'eleven_turbo_v2',
        defaultLlm: process.env.DEFAULT_AGENT_LLM ?? 'gpt-4o-mini',
      },
    },
  },
];

const normalized = $('Restore Normalized Telegram Update').item.json;
const user = typeof $json.user_record === 'string' ? JSON.parse($json.user_record) : $json.user_record;
const triggerUpdate = $('Telegram Trigger').item.json;
const rawMessageText = user && typeof triggerUpdate.message?.text === 'string' ? triggerUpdate.message.text : '';
const trimmedText = rawMessageText.trim();
const messageText = user ? rawMessageText : normalized.messageText;
const command = user ? (trimmedText.split(/\s+/)[0] || '') : normalized.command;

return [{ json: { ...normalized, ...$json, messageText, trimmedText: user ? trimmedText : normalized.trimmedText, command } }];

const user = typeof $json.user_record === 'string' ? JSON.parse($json.user_record) : $json.user_record;
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
const activeAgent = typeof $json.active_agent === 'string' ? JSON.parse($json.active_agent) : $json.active_agent;
const settings = $json.settings ?? {};
const maxAgents = Number.isFinite(settings.maxAgentsPerUser) ? settings.maxAgentsPerUser : 3;

const button = (text, data) => ({ text, callback_data: data });
const agentsKeyboard = () => {
  const rows = agents.map((agent) => [button(agent.is_active ? `✓ ${agent.display_name}` : agent.display_name, `ag:sel:${agent.id}`)]);
  if (agents.length < maxAgents) rows.push([button('Создать агента', 'ag:new')]);
  return { inline_keyboard: rows };
};
const actionsKeyboard = () => ({
  inline_keyboard: [
    [button('Изменить prompt', 'ag:p')],
    [button('Изменить приветствие', 'ag:w')],
    [button('Обновить knowledge', 'ag:k')],
    [button('Список агентов', 'ag:list')],
  ],
});
const menuText = () => [
  'Доступ открыт.',
  `Лимит агентов: ${maxAgents}.`,
  'Команда /agents покажет список агентов и действия.',
].join('\n');
const reply = (route, text, extra = {}) => [{ json: { ...$json, route, replyText: text, replyMarkup: extra.replyMarkup ?? null, ...extra } }];
const callbackExtra = (extra = {}) => ($json.isCallback ? { ...extra, answerCallback: true } : extra);

if (!$json.telegramUserId || !$json.chatId) {
  return reply('reply', 'Не вижу Telegram user id или chat id. Попробуйте отправить сообщение еще раз.', callbackExtra());
}

if (!user) {
  if (!$json.accessPasswordConfigured) {
    return reply('reply', 'Доступ временно не настроен. Попробуйте позже.', callbackExtra());
  }
  if ($json.isTextMessage && $json.accessPasswordMatched) {
    return reply('register_user', menuText());
  }
  return reply('reply', 'Пришлите пароль доступа текстовым сообщением.', callbackExtra());
}

if ($json.isCallback && $json.callbackData) {
  if ($json.callbackData === 'ag:list') {
    return reply('reply', agents.length ? 'Ваши агенты:' : 'У вас пока нет агентов.', { replyMarkup: agentsKeyboard(), answerCallback: true });
  }
  if ($json.callbackData === 'ag:new') {
    if (agents.length >= maxAgents) {
      return reply('reply', `Лимит агентов исчерпан: ${maxAgents}.`, { answerCallback: true });
    }
    return reply('set_state', 'Как назвать нового агента? Пришлите имя текстом.', { nextState: 'awaiting_agent_name', answerCallback: true });
  }
  if ($json.callbackData.startsWith('ag:sel:')) {
    const localAgentId = Number.parseInt($json.callbackData.slice('ag:sel:'.length), 10);
    const selected = agents.find((agent) => agent.id === localAgentId);
    if (!selected) return reply('reply', 'Этот агент вам не принадлежит. Выберите агента через /agents.', { answerCallback: true });
    return reply('set_active_agent', `Выбран агент: ${selected.display_name}`, { activeAgentId: localAgentId, nextState: 'idle', replyMarkup: actionsKeyboard(), answerCallback: true });
  }
  if (['ag:p', 'ag:w', 'ag:k'].includes($json.callbackData)) {
    if (!activeAgent?.id) return reply('reply', 'Сначала выберите агента через /agents.', { answerCallback: true });
    const states = { 'ag:p': 'awaiting_prompt', 'ag:w': 'awaiting_welcome', 'ag:k': 'awaiting_knowledge' };
    const texts = {
      'ag:p': 'Пришлите новый prompt текстом.',
      'ag:w': 'Пришлите новое приветствие текстом.',
      'ag:k': 'Пришлите новый knowledge content текстом.',
    };
    return reply('set_state', texts[$json.callbackData], { nextState: states[$json.callbackData], answerCallback: true });
  }
  return reply('reply', 'Неизвестное действие. Откройте /agents.', { answerCallback: true });
}

if ($json.command === '/start') return reply('reset_to_menu', menuText(), { nextState: 'idle' });
if ($json.command === '/agents') return reply('reply', agents.length ? 'Ваши агенты:' : 'У вас пока нет агентов.', { replyMarkup: agentsKeyboard() });

if (user.dialog_state === 'awaiting_agent_name') {
  if (!$json.isTextMessage || !$json.trimmedText) return reply('reply', 'Имя агента нужно отправить текстом.');
  if (agents.length >= maxAgents) return reply('reset_to_menu', `Лимит агентов исчерпан: ${maxAgents}.`, { nextState: 'idle' });
  return reply('create_agent', 'Создаю агента...', { agentName: $json.trimmedText });
}

if (['awaiting_prompt', 'awaiting_welcome', 'awaiting_knowledge'].includes(user.dialog_state)) {
  if (!activeAgent?.id) return reply('reset_to_menu', 'Сначала выберите агента через /agents.', { nextState: 'idle' });
  if (!$json.isTextMessage || !$json.trimmedText) return reply('reply', 'Пришлите текст. Файлы, голосовые и прочая роскошь в этой версии не принимаются.');
  const routeByState = {
    awaiting_prompt: 'update_prompt',
    awaiting_welcome: 'update_welcome',
    awaiting_knowledge: 'update_knowledge',
  };
  return reply(routeByState[user.dialog_state], 'Обновляю агента...', { newText: $json.trimmedText });
}

return reply('reply', 'Откройте /agents, чтобы выбрать или создать агента.');

if (!$json.replyMarkup) {
  return [];
}

const telegramRequestBody = {
  chat_id: $json.chatId,
  text: $json.replyText,
  reply_markup: $json.replyMarkup,
};

if ($json.messageId) {
  telegramRequestBody.reply_to_message_id = $json.messageId;
}

return [{ json: { ...$json, telegramRequestBody } }];

const pendingText = [
  'Действие принято, но узлы ElevenLabs еще не подключены в этом экспортированном workflow.',
  'Продолжу настройку следующим шагом.',
].join('\n');

return [{ json: { ...$json, replyText: pendingText, replyMarkup: null } }];

const settings = $json.settings ?? {};
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
const maxAgents = Number.isFinite(settings.maxAgentsPerUser) ? settings.maxAgentsPerUser : 3;
const agentName = String($json.agentName ?? '').trim().slice(0, 80);

if (!$json.user_record || !agentName) {
  throw new Error('Cannot create ElevenLabs agent without a registered user and agent name.');
}

if (agents.length >= maxAgents) {
  throw new Error(`Agent limit exceeded before create request: ${maxAgents}.`);
}

const defaultPrompt = settings.defaultPrompt ?? 'You are a helpful voice assistant.';
const defaultWelcome = settings.defaultWelcome ?? 'Hello, how can I help you today?';
const defaultLanguage = settings.defaultLanguage ?? 'en';
const defaultVoiceId = settings.defaultVoiceId ?? 'cjVigY5qzO86Huf0OWal';
const defaultTtsModelId = settings.defaultTtsModelId ?? 'eleven_turbo_v2';
const defaultLlm = settings.defaultLlm ?? 'gemini-2.5-flash';
const reservationKey = `pending:${$json.telegramUserId}:${Date.now()}:${Math.random().toString(36).slice(2)}`;

const elevenLabsCreateAgentBody = {
  name: agentName,
  tags: ['telegram-bot', 'n8n-managed'],
  conversation_config: {
    agent: {
      first_message: defaultWelcome,
      language: defaultLanguage,
      prompt: {
        prompt: defaultPrompt,
        llm: defaultLlm,
      },
    },
    tts: {
      voice_id: defaultVoiceId,
      model_id: defaultTtsModelId,
    },
  },
};

return [{ json: { ...$json, agentName, defaultPrompt, defaultWelcome, reservationKey, elevenLabsCreateAgentBody } }];

const route = $('Prepare Reserved Agent Create').item.json;
const saved = $('Save Created Agent').item.json;
const agents = typeof $json.agents === 'string' ? JSON.parse($json.agents) : ($json.agents ?? []);
if (!saved?.id) {
  throw new Error('Created ElevenLabs agent was not saved locally, most likely because the user agent limit was reached concurrently.');
}

const createdAgentName = saved.display_name ?? route.agentName;
const activeLocalId = Number(saved.id);

const button = (text, data) => ({ text, callback_data: data });
const actionsKeyboard = () => ({
  inline_keyboard: [
    [button('Изменить prompt', 'ag:p')],
    [button('Изменить приветствие', 'ag:w')],
    [button('Обновить knowledge', 'ag:k')],
    [button('Список агентов', 'ag:list')],
  ],
});

return [{
  json: {
    ...route,
    ...$json,
    agents,
    activeAgentId: activeLocalId,
    replyText: `Агент создан: ${createdAgentName}.`,
    replyMarkup: actionsKeyboard(),
  },
}];

const payload = $('Build ElevenLabs Agent Payload').item.json;
const reserved = typeof $json.reserved_agent === 'string' ? JSON.parse($json.reserved_agent) : $json.reserved_agent;

if (reserved?.id) {
  return [];
}

return [{
  json: {
    ...payload,
    ...$json,
    replyText: `Лимит агентов исчерпан: ${$json.max_agents ?? payload.settings?.maxAgentsPerUser ?? 3}.`,
    replyMarkup: null,
    nextState: 'idle',
  },
}];

const payload = $('Build ElevenLabs Agent Payload').item.json;
const reserved = typeof $json.reserved_agent === 'string' ? JSON.parse($json.reserved_agent) : $json.reserved_agent;

if (!reserved?.id) {
  return [];
}

return [{
  json: {
    ...payload,
    reservationLocalAgentId: reserved.id,
    reservationKey: reserved.elevenlabs_agent_id,
  },
}];
